import sys

def remove_opt(nums):
    if len(nums) <= 2:
        return nums
    slow = 2
    for fast in range(2, len(nums)):
        if nums[fast] != nums[slow - 2]:
            nums[slow] = nums[fast]
            slow += 1
    return nums[:slow]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    res = remove_opt(nums)
    print(len(res))
    print(' '.join(map(str, res)))
